  "controle-comparer": ["../bibliotheque/illu-x-detective.webp", "Loupe représentant le passage de l’indice à la localisation."],
  "registre-resultat": ["../bibliotheque/icones/ico-registre.png", "Pictogramme du registre de contrôle."],
  "controle-trace": ["../bibliotheque/icones/ico-registre.png", "Pictogramme du registre de l’équipement."],
  "ordre-final": ["../bibliotheque/illu-x-detective.webp", "Loupe regroupant les points contrôlés de l’installation."],
